/**
 * Comparison operator for threshold checks:
 * - Below: Trigger when value < threshold
 * - BelowOrEqual: Trigger when value <= threshold
 * - Above: Trigger when value > threshold
 * - AboveOrEqual: Trigger when value >= threshold
 * - AboveOrBelow: Trigger when value is outside a range
 */
export type MonitorOperator = typeof MonitorOperator[keyof typeof MonitorOperator];


export const MonitorOperator = {
  Below: 'Below',
  BelowOrEqual: 'BelowOrEqual',
  Above: 'Above',
  AboveOrEqual: 'AboveOrEqual',
  AboveOrBelow: 'AboveOrBelow',
} as const;

/**
 * Type of monitoring check to perform:
 * - Threshold: Compares a numeric value against a threshold
 * - MatchEvent: Looks for specific events or patterns
 * - AnomalyDetection: Identifies unusual patterns based on historical data
 */
export type MonitorType = typeof MonitorType[keyof typeof MonitorType];


export const MonitorType = {
  Threshold: 'Threshold',
  MatchEvent: 'MatchEvent',
  AnomalyDetection: 'AnomalyDetection',
} as const;

/**
 * Configuration for a monitoring rule. Monitors can be configured to:
 * - Check threshold values (e.g., CPU usage > 90%)
 * - Match specific events in logs
 * - Detect anomalies based on historical patterns
 * Each monitor runs on a specified interval and can trigger notifications through configured notifiers.
 */
export interface Monitor {
  /** Whether to alert when no data is received */
  alertOnNoData?: boolean;
  /**
     * APL (Axiom Processing Language) query string used for monitoring.
     * This query defines what data to analyze and how to process it.
     * At least one of aplQuery or mplQuery must be provided.
     */
  aplQuery?: string;
  /** Name of the column to monitor */
  columnName?: string;
  /**
     * Number of days to compare for anomaly detection
     * @maximum 7
     */
  compareDays?: number;
  /** Timestamp when the monitor was created */
  createdAt?: string;
  /** ID of the user who created the monitor */
  createdBy?: string;
  /** Detailed description of the monitor's purpose */
  description?: string;
  /** Whether the monitor is currently disabled */
  disabled?: boolean;
  /**
     * Timestamp until when the monitor should remain disabled
     * @nullable
     */
  disabledUntil?: string | null;
  /**
     * How frequently the monitor should run, in minutes.
     * Minimum value is 1 minute.
     * @minimum 1
     */
  intervalMinutes?: number;
  /**
     * MPL (Metrics Processing Language) query string for metrics-based monitoring.
     * Use this as an alternative to aplQuery for metrics datasets.
     * At least one of aplQuery or mplQuery must be provided.
     */
  mplQuery?: string;
  /** Name of the monitor */
  name: string;
  /**
     * List of notifier IDs that will receive alerts.
     * Notifiers can be email, Slack, webhook endpoints, etc.
     */
  notifierIds?: string[];
  /** Whether to group notifications */
  notifyByGroup?: boolean;
  /** Whether to send notifications on every check */
  notifyEveryRun?: boolean;
  /**
     * Comparison operator for threshold checks:
     * - Below: Trigger when value < threshold
     * - BelowOrEqual: Trigger when value <= threshold
     * - Above: Trigger when value > threshold
     * - AboveOrEqual: Trigger when value >= threshold
     * - AboveOrBelow: Trigger when value is outside a range
     */
  operator?: MonitorOperator;
  /**
     * Time window to evaluate in each check, in minutes.
     * For example, "last 5 minutes of data"
     * @minimum 1
     */
  rangeMinutes?: number;
  /** Whether the alert can be manually resolved */
  resolvable?: boolean;
  /**
     * Delay in seconds before triggering the alert
     * @maximum 86400
     */
  secondDelay?: number;
  /** Whether to skip resolved alerts */
  skipResolved?: boolean;
  /** Threshold value for triggering the alert */
  threshold?: number;
  /**
     * Tolerance percentage for anomaly detection
     * @maximum 100
     */
  tolerance?: number;
  /** Number of positive results needed before triggering */
  triggerAfterNPositiveResults?: number;
  /**
     * Number of consecutive check runs that must fail before triggering an alert.
     * Use this to avoid alerting on temporary spikes.
     */
  triggerFromNRuns?: number;
  /**
     * Type of monitoring check to perform:
     * - Threshold: Compares a numeric value against a threshold
     * - MatchEvent: Looks for specific events or patterns
     * - AnomalyDetection: Identifies unusual patterns based on historical data
     */
  type: MonitorType;
  /** Timestamp when the monitor was last updated */
  updatedAt?: string;
}

